use crate::bridge::extern_c_api as extern_api;
use data::*;

use proptest::prelude::*;

/// container for component's incoming port values
pub struct PreStateContainer {
  pub api_channel1: bool,
  pub api_channel2: bool,
  pub api_channel3: bool,
  pub api_channel4: bool,
}

/// setter for component's incoming port values
pub fn put_concrete_inputs_container(container: PreStateContainer)
{
  put_channel1(container.api_channel1);
  put_channel2(container.api_channel2);
  put_channel3(container.api_channel3);
  put_channel4(container.api_channel4);
}

/// setter for component's incoming port values
pub fn put_concrete_inputs(
  channel1: bool,
  channel2: bool,
  channel3: bool,
  channel4: bool)
{
  put_channel1(channel1);
  put_channel2(channel2);
  put_channel3(channel3);
  put_channel4(channel4);
}

/// setter for IN DataPort
pub fn put_channel1(value: bool)
{
  *extern_api::IN_channel1.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_channel2(value: bool)
{
  *extern_api::IN_channel2.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_channel3(value: bool)
{
  *extern_api::IN_channel3.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// setter for IN DataPort
pub fn put_channel4(value: bool)
{
  *extern_api::IN_channel4.lock().unwrap_or_else(|e| e.into_inner()) = Some(value)
}

/// getter for OUT DataPort
pub fn get_actuate() -> bool
{
  return extern_api::OUT_actuate.lock().unwrap_or_else(|e| e.into_inner()).expect("Not expecting None")
}
